int has_pair_sum(DNode* head, int S) {
    DNode* lo = head;
    DNode* hi = head;
    while (hi->next) hi = hi->next;
    while (lo != hi && hi->next != lo) {
        long long sum = (long long)lo->data + (long long)hi->data;
        if (sum == S) return 1;
        if (sum < S) lo = lo->next;
        else hi = hi->prev;
    }
    return 0;
}

