    DNode* head = NULL;
    DNode* tail = NULL;
    for (int i = 0; i < n; i++) {
        int v;
        std::cin >> v;
        DNode* node = new DNode();
        node->data = v;
        node->prev = tail;
        node->next = NULL;
        if (tail) tail->next = node;
        else head = node;
        tail = node;
    }
    DNode* res = dll_reverse(head);
    bool first = true;
    for (DNode* cur = res; cur != NULL; cur = cur->next) {
        if (!first) std::cout << ' ';
        std::cout << cur->data;
        first = false;
    }
    std::cout << "\n";
    return 0;
}
